#requires -Version 5.1

# Single source of truth for the post-install menu, the GUI and automation.
# N must match the script file prefix so console numbers stay meaningful.
$AstraModules = @(
    [pscustomobject]@{ N = 1; Group = 'Performance'; Label = 'Ultimate Performance power plan'; Script = '01-PowerPlan.ps1'; Risk = $false; Note = 'Switches the active power scheme between Ultimate Performance and Balanced.' }
    [pscustomobject]@{ N = 2; Group = 'Performance'; Label = 'Core parking off'; Script = '02-CoreParking.ps1'; Risk = $false; Note = 'Keeps every core unparked: CPMINCORES and CPMAXCORES at 100.' }
    [pscustomobject]@{ N = 3; Group = 'Performance'; Label = 'CPU idle states off'; Script = '03-CpuIdle.ps1'; Risk = $false; Note = 'Disables processor idle on AC. Lower latency, higher idle temperatures. Desktops only.' }
    [pscustomobject]@{ N = 4; Group = 'Performance'; Label = 'Power throttling off'; Script = '04-PowerThrottling.ps1'; Risk = $false; Note = 'Stops Windows from throttling background and foreground apps.' }
    [pscustomobject]@{ N = 5; Group = 'Performance'; Label = 'Fast startup off'; Script = '05-FastStartup.ps1'; Risk = $false; Note = 'Full shutdown every time, so drivers and services reload cleanly.' }
    [pscustomobject]@{ N = 6; Group = 'Performance'; Label = 'Hibernation off'; Script = '06-Hibernation.ps1'; Risk = $false; Note = 'Removes hiberfil.sys and the hibernate power state. Frees disk space.' }
    [pscustomobject]@{ N = 7; Group = 'Performance'; Label = 'Memory compression off'; Script = '07-MemoryCompression.ps1'; Risk = $false; Note = 'Trades memory savings for less CPU work. Wants 16 GB or more.' }
    [pscustomobject]@{ N = 8; Group = 'Performance'; Label = 'Global timer resolution requests'; Script = '08-TimerResolution.ps1'; Risk = $false; Note = 'Lets apps ask the kernel for 0.5 ms timers on Windows 11.' }
    [pscustomobject]@{ N = 9; Group = 'Gaming'; Label = 'Game Mode, DVR and capture off'; Script = '09-GameMode.ps1'; Risk = $false; Note = 'Standard Game Mode tuning plus Game Bar capture, DVR and fullscreen-optimization flags.' }
    [pscustomobject]@{ N = 10; Group = 'Gaming'; Label = 'MMCSS game task priority'; Script = '10-Mmcss.ps1'; Risk = $false; Note = 'Raises the Games multimedia task so game threads outrank background media work.' }
    [pscustomobject]@{ N = 11; Group = 'Network'; Label = 'Network latency (Nagle and NetBIOS off)'; Script = '11-NetworkLatency.ps1'; Risk = $false; Note = 'Per-adapter Nagle and NetBIOS tuning, multicast DNS and WPAD noise off.' }
    [pscustomobject]@{ N = 12; Group = 'Performance'; Label = 'Background services off'; Script = '12-Services.ps1'; Risk = $true; Note = 'Stops DiagTrack, SysMain, WSearch, Xbox, NDU and WER. Some Windows features rely on these.' }
    [pscustomobject]@{ N = 13; Group = 'Privacy'; Label = 'Telemetry off'; Script = '13-Telemetry.ps1'; Risk = $false; Note = 'Telemetry policy, ads ID, feedback prompts and the CEIP scheduled tasks.' }
    [pscustomobject]@{ N = 14; Group = 'Privacy'; Label = 'Privacy (search, activity, location)'; Script = '14-Privacy.ps1'; Risk = $false; Note = 'Web search, Cortana consent, activity history and location access off.' }
    [pscustomobject]@{ N = 15; Group = 'Shell'; Label = 'Visual effects off'; Script = '15-VisualEffects.ps1'; Risk = $false; Note = 'Transparency and menu animations off for a snappier shell.' }
    [pscustomobject]@{ N = 16; Group = 'Shell'; Label = 'Explorer quality of life'; Script = '16-Explorer.ps1'; Risk = $false; Note = 'Classic right-click menu, This PC, clock seconds, file extensions, clipboard, long paths.' }
    [pscustomobject]@{ N = 17; Group = 'Shell'; Label = 'Taskbar cleaned up'; Script = '17-Taskbar.ps1'; Risk = $false; Note = 'Widgets, chat, task view button, search box and alignment.' }
    [pscustomobject]@{ N = 18; Group = 'System'; Label = 'Windows Update drivers blocked'; Script = '18-DriverUpdates.ps1'; Risk = $false; Note = 'Keeps your vendor GPU driver instead of letting Windows Update replace it.' }
    [pscustomobject]@{ N = 19; Group = 'System'; Label = 'OneDrive sync off'; Script = '19-OneDrive.ps1'; Risk = $false; Note = 'Disables OneDrive file sync and stops the running client.' }
    [pscustomobject]@{ N = 20; Group = 'Security'; Label = 'Defender real-time off'; Script = '20-Defender.ps1'; Risk = $true; Note = 'Turns off real-time protection. A security trade-off; tamper protection may block it.' }
    [pscustomobject]@{ N = 21; Group = 'Appearance'; Label = 'Wallpaper theme (ON red/purple)'; Script = '21-Wallpaper.ps1'; Risk = $false; Note = 'ON applies the red and purple wallpaper, OFF applies midnight blue.' }
    [pscustomobject]@{ N = 22; Group = 'Shell'; Label = 'Startup app delay removed'; Script = '22-StartupDelay.ps1'; Risk = $false; Note = 'Removes the built-in delay before startup apps launch at sign-in.' }
    [pscustomobject]@{ N = 23; Group = 'Shell'; Label = 'Search highlights off'; Script = '23-SearchHighlights.ps1'; Risk = $false; Note = 'Removes the rotating illustration and tips inside the search box.' }
    [pscustomobject]@{ N = 24; Group = 'Shell'; Label = 'Lock screen tips and suggestions off'; Script = '24-Suggestions.ps1'; Risk = $false; Note = 'Lock screen tips, Settings suggestions and Windows tips.' }
    [pscustomobject]@{ N = 25; Group = 'Shell'; Label = 'Recent and frequent files hidden'; Script = '25-ExplorerRecent.ps1'; Risk = $false; Note = 'Hides the recent and frequent lists in Explorer Home.' }
    [pscustomobject]@{ N = 26; Group = 'Input'; Label = 'Mouse acceleration off'; Script = '26-MouseAcceleration.ps1'; Risk = $false; Note = 'Raw 1:1 mouse input: no pointer acceleration, no thresholds.' }
    [pscustomobject]@{ N = 27; Group = 'System'; Label = 'Edge startup boost and background off'; Script = '27-EdgeBackground.ps1'; Risk = $false; Note = 'Edge policies: no startup boost, no background mode, no preloading.' }
    [pscustomobject]@{ N = 28; Group = 'System'; Label = 'Windows Update auto-restart suppressed'; Script = '28-UpdateAutoRestart.ps1'; Risk = $false; Note = 'Windows Update will not restart the machine while you are signed in.' }
    [pscustomobject]@{ N = 29; Group = 'Network'; Label = 'Delivery Optimization peer downloads off'; Script = '29-DeliveryOptimization.ps1'; Risk = $false; Note = 'No uploads of update content to other PCs; downloads come from Microsoft only.' }
    [pscustomobject]@{ N = 30; Group = 'Performance'; Label = 'USB selective suspend off'; Script = '30-UsbSelectiveSuspend.ps1'; Risk = $false; Note = 'Stops Windows suspending USB devices to save power (AC and DC).' }
    [pscustomobject]@{ N = 31; Group = 'Privacy'; Label = 'Copilot off'; Script = '31-Copilot.ps1'; Risk = $false; Note = 'Copilot policy on user and machine, plus the taskbar button.' }
    [pscustomobject]@{ N = 32; Group = 'Privacy'; Label = 'Recall off'; Script = '32-Recall.ps1'; Risk = $false; Note = 'Windows AI data analysis policy: Recall snapshots off.' }
    [pscustomobject]@{ N = 33; Group = 'Privacy'; Label = 'AutoPlay off'; Script = '33-AutoPlay.ps1'; Risk = $false; Note = 'Stops AutoPlay prompts when media or drives are connected.' }
    [pscustomobject]@{ N = 34; Group = 'Privacy'; Label = 'Remote Assistance off'; Script = '34-RemoteAssistance.ps1'; Risk = $false; Note = 'Remote Assistance invitations off.' }
    [pscustomobject]@{ N = 35; Group = 'Network'; Label = 'QoS reserved bandwidth cleared'; Script = '35-QosReserved.ps1'; Risk = $false; Note = 'Removes the 20 percent bandwidth reservation from the QoS scheduler.' }
    [pscustomobject]@{ N = 36; Group = 'Performance'; Label = 'Prefetch off'; Script = '36-Prefetch.ps1'; Risk = $false; Note = 'Prefetcher and Superfetch off. SSD-era tweak; can slow cold starts.' }
    [pscustomobject]@{ N = 37; Group = 'Network'; Label = 'Network throttling index off'; Script = '37-NetworkThrottling.ps1'; Risk = $false; Note = 'Removes the MMCSS 10 packets-per-ms throttle on non-media traffic.' }
    [pscustomobject]@{ N = 38; Group = 'Privacy'; Label = 'Consumer features off'; Script = '38-ConsumerFeatures.ps1'; Risk = $false; Note = 'Disables suggested apps and consumer content policy.' }
    [pscustomobject]@{ N = 39; Group = 'Shell'; Label = 'Lock screen off'; Script = '39-LockScreen.ps1'; Risk = $false; Note = 'Skips the lock screen so sign-in goes straight to the password field.' }
    [pscustomobject]@{ N = 40; Group = 'System'; Label = 'Print Spooler off'; Script = '40-Spooler.ps1'; Risk = $true; Note = 'Stops printing until the service is re-enabled. Off by default in presets.' }
    [pscustomobject]@{ N = 41; Group = 'System'; Label = 'Store auto-update off'; Script = '41-StoreAutoUpdate.ps1'; Risk = $false; Note = 'Microsoft Store apps stop updating in the background.' }
    [pscustomobject]@{ N = 42; Group = 'Debloat'; Label = 'Debloat Light'; Script = '42-DebloatLight.ps1'; Risk = $false; Note = 'Removes Clipchamp, Bing news/weather/search, Tips, Solitaire and People for every account and as provisioned packages. ON applies the tier; apps cannot be restored automatically.' }
    [pscustomobject]@{ N = 43; Group = 'Debloat'; Label = 'Debloat Moderate'; Script = '43-DebloatModerate.ps1'; Risk = $false; Note = 'Light plus Mail, Maps, Teams, Phone Link, Office hub, 3D Viewer, Print 3D, Family safety, Alarms, media apps, To Do, Skype and Feedback Hub, for every account. ON applies the tier; not reversible automatically.' }
    [pscustomobject]@{ N = 44; Group = 'Debloat'; Label = 'Debloat Extreme (caution)'; Script = '44-DebloatExtreme.ps1'; Risk = $true; Note = 'Moderate plus Microsoft Store, Photos, Camera, Xbox app, Game Bar, Outlook, Dev Home, Copilot (all variants) and OneDrive; each removed package also loses its data folders and per-user AppModel keys, and OneDrive install data/settings are cleaned while synced files stay untouched. The Store comes back with wsreset -i; apps must be reinstalled from the Store or removed.json and deleted data is permanent.' }
    [pscustomobject]@{ N = 45; Group = 'Appearance'; Label = 'True dark mode (Windows and apps)'; Script = '45-DarkMode.ps1'; Risk = $false; Note = 'Both light-theme values off; broadcasts a theme refresh. Third-party apps may need restarting.' }
    [pscustomobject]@{ N = 46; Group = 'Shell'; Label = 'Taskbar End task'; Script = '46-EndTask.ps1'; Risk = $false; Note = 'Windows 11 23H2+. Right-click a running taskbar app to terminate it; unsaved work can be lost.' }
    [pscustomobject]@{ N = 47; Group = 'CPU'; Label = 'CPU boost policy: Aggressive (AC)'; Script = '47-CpuBoost.ps1'; Risk = $true; Note = 'PERFBOOSTMODE 2 on the active scheme, AC only. Not an overclock: firmware controls clocks. Extra heat/power possible; OFF restores the saved index for this scheme.' }
    [pscustomobject]@{ N = 48; Group = 'CPU'; Label = 'CPU energy preference: performance (AC)'; Script = '48-CpuEpp.ps1'; Risk = $true; Note = 'EPP 0 favors performance on AC. Can increase power use; benchmark before keeping it. OFF restores the saved active-scheme value.' }
    [pscustomobject]@{ N = 49; Group = 'GPU'; Label = 'Hardware-accelerated GPU scheduling'; Script = '49-GpuScheduling.ps1'; Risk = $true; Note = 'Requests HAGS on supported hardware/driver; reboot required. ON shows configuration, not proof it is running. Compare frame times; OFF restores the saved registry value.' }
    [pscustomobject]@{ N = 50; Group = 'GPU'; Label = 'Windowed DX10/DX11 optimizations'; Script = '50-WindowedGaming.ps1'; Risk = $false; Note = 'Requests Windows windowed/borderless optimizations for compatible DX10/DX11 games. Restart games; Auto HDR may override OFF. Other global graphics preferences are preserved.' }
    [pscustomobject]@{ N = 51; Group = 'Gaming'; Label = 'Rainbow Six Siege profile'; Script = '51-SiegeProfile.ps1'; Risk = $false; Note = 'GPU preference and existing DISPLAY VSync value only. OFF restores saved values. Close the game first; no anti-cheat executable or renderer flag changes.' }
    [pscustomobject]@{ N = 52; Group = 'Gaming'; Label = 'Fortnite profile'; Script = '52-FortniteProfile.ps1'; Risk = $false; Note = 'GPU preference and existing VSync/dynamic-resolution values. Render mode, FPS cap and Reflex stay manual. Close the game; OFF restores saved values.' }
    [pscustomobject]@{ N = 53; Group = 'Gaming'; Label = 'Call of Duty HQ / Warzone profile'; Script = '53-CodProfile.ps1'; Risk = $false; Note = 'Detects Steam COD HQ or default Battle.net installs. GPU preference only; no RenderWorkerCount/VRAM edits. Custom paths use GameProfiles.ps1 -Cod -InstallDirectory. OFF restores saved preference.' }
    [pscustomobject]@{ N = 54; Group = 'Gaming'; Label = 'Apex Legends profile'; Script = '54-ApexProfile.ps1'; Risk = $false; Note = 'Installed game GPU preference plus a manual graphics guide. No autoexec or network flags. Custom installs use -Apex -InstallDirectory; OFF restores saved preference.' }
    [pscustomobject]@{ N = 55; Group = 'Gaming'; Label = 'Counter-Strike 2 profile'; Script = '55-CS2Profile.ps1'; Risk = $false; Note = 'CS2 GPU preference with manual graphics/Reflex guidance. No CS:GO launch flags, priorities or anti-cheat changes. OFF restores saved preference.' }
    [pscustomobject]@{ N = 56; Group = 'Appearance'; Label = 'Live wallpaper (hair sway, glow pulse)'; Script = '56-LiveWallpaper.ps1'; Risk = $true; IndividualOnly = $true; Note = 'Builds the lightweight native Astra host and applies Pictures\Astra\Astra-Personal-Live to the primary screen at about 24 fps with hair sway and a red/blue glow pulse. Uses no browser runtime and pauses behind fullscreen apps. Adds an Astra startup shortcut; OFF stops only this host and restores the saved static background. Personal files are not bundled.' }
    [pscustomobject]@{ N = 57; Group = 'Appearance'; Label = 'Import personal static wallpaper'; Script = '57-PersonalWallpaper.ps1'; Risk = $false; IndividualOnly = $true; Note = 'Imports Pictures\Astra\personal-wallpaper.png (or the personal Astra image). Missing files are skipped. OFF restores the saved static wallpaper and fit. Excluded from bulk actions.' }
    [pscustomobject]@{ N = 58; Group = 'Performance'; Label = 'Background apps off'; Script = '58-BackgroundApps.ps1'; Risk = $false; Note = 'Stops Store and desktop apps from running in the background for this user (GlobalUserDisabled=1, BackgroundAppGlobalToggle=0). Sign out so every app honours it; OFF returns to the Windows default.' }
    [pscustomobject]@{ N = 59; Group = 'Performance'; Label = 'Foreground priority boost'; Script = '59-PriorityBoost.ps1'; Risk = $false; Note = 'Sets the system-wide Win32PrioritySeparation value to 38 (short, fixed quantum with foreground boost). A scheduling preference, not an FPS promise; benchmark before keeping it. OFF returns to the Windows default (2).' }
    [pscustomobject]@{ N = 60; Group = 'Shell'; Label = 'Sync provider notifications hidden'; Script = '60-SyncProviderAds.ps1'; Risk = $false; Note = 'Hides the OneDrive and other sync-provider notification prompts in Explorer. OFF deletes the value and returns to the Windows default.' }
    [pscustomobject]@{ N = 61; Group = 'Shell'; Label = 'Aero Shake off'; Script = '61-AeroShake.ps1'; Risk = $false; Note = 'Disables the shake-a-window gesture that minimizes every other window. OFF deletes the value and returns to the Windows default.' }
    [pscustomobject]@{ N = 62; Group = 'Debloat'; Label = 'Debloat Insane (advanced, irreversible)'; Script = '62-DebloatInsane.ps1'; Risk = $true; IndividualOnly = $true; Note = 'WARNING: applies the cumulative Insane tier and removes the last Microsoft apps: Calculator, Notepad, Snipping Tool, Paint, Sticky Notes, Get Help, OneNote, Wallet and the Xbox speech overlay. Each removed package also loses its package-data folders (all profiles plus ProgramData) and per-user AppModel registry keys. The Store is already gone. Apps cannot be restored automatically and deleted data is permanent; winget is kept for reinstall. Excluded from bulk actions.' }
    [pscustomobject]@{ N = 63; Group = 'System'; Label = 'Services Insane (advanced, restorable)'; Script = '63-ServicesInsane.ps1'; Risk = $true; IndividualOnly = $true; Note = 'WARNING: cumulative Insane service tier disables Windows Update/BITS, RDP host, Xbox/Game Pass, biometrics, camera frame server, smart cards, diagnostics, UPnP discovery, VPN dialing, update orchestration and 10 per-user service templates, and raises the service-host split threshold (reboot) so fewer svchost processes remain. Disabled services also lose their cache/report folders and stale per-user service keys, and every removal is recorded. Startup types are snapshotted before the first change; OFF restores service-state.json, user-service-state.json and kernel-state.json exactly and starts the services that were running, but deleted service caches are not restored. Excluded from bulk actions.' }
    [pscustomobject]@{ N = 64; Group = 'Shell'; Label = 'Animations off (whole OS)'; Script = '64-Animations.ps1'; Risk = $false; Note = 'Turns off window minimize/maximize fades (MinAnimate=0) and taskbar animations (TaskbarAnimations=0) for the signed-in user. Sign out or restart Explorer to finish. OFF restores both Windows defaults.' }
    [pscustomobject]@{ N = 65; Group = 'Performance'; Label = 'PCIe link power saving off (AC)'; Script = '65-PciePower.ps1'; Risk = $false; Note = 'Sets PCI Express link state power management to off on AC so the GPU and NVMe links stop dropping into low-power states. Desktop-first; watch idle power and benchmark. OFF restores the saved active-scheme value.' }
    [pscustomobject]@{ N = 66; Group = 'Performance'; Label = 'Disk idle timeout off (AC)'; Script = '66-DiskIdle.ps1'; Risk = $false; Note = 'Keeps drives spinning instead of sleeping after idle. Can add heat and noise on laptops; AC only. OFF restores the saved disk timeout.' }
    [pscustomobject]@{ N = 67; Group = 'CPU'; Label = 'Kernel dynamic tick off (experimental)'; Script = '67-DynamicTick.ps1'; Risk = $true; Note = 'Writes disabledynamictick=yes to the boot configuration. Reboot required; benchmark frame times and latency before keeping it. OFF restores the previous BCD state.' }
    [pscustomobject]@{ N = 68; Group = 'Gaming'; Label = 'Notification pop-ups off'; Script = '68-Notifications.ps1'; Risk = $false; Note = 'Turns off Windows toast pop-ups for this user. Focus Assist and per-app notification settings are unchanged. OFF restores the default.' }
    [pscustomobject]@{ N = 69; Group = 'Shell'; Label = 'Menu show delay 0'; Script = '69-MenuDelay.ps1'; Risk = $false; Note = 'Removes the 400 ms delay before menus fly out. Sign out or restart Explorer to finish. OFF restores the Windows default.' }
    [pscustomobject]@{ N = 70; Group = 'Input'; Label = 'Accessibility shortcut keys off'; Script = '70-A11yKeys.ps1'; Risk = $false; Note = 'Disables the Sticky, Filter and Toggle Keys hotkeys and Narrator Win+Enter. Re-enable any of them in Settings > Accessibility. OFF restores the defaults.' }
    [pscustomobject]@{ N = 71; Group = 'Shell'; Label = 'Windows Ink Workspace button hidden'; Script = '71-InkWorkspace.ps1'; Risk = $false; Note = 'Hides the pen workspace button for the signed-in user. OFF restores it.' }
    [pscustomobject]@{ N = 72; Group = 'System'; Label = 'Edge gaming policies'; Script = '72-EdgeGaming.ps1'; Risk = $false; Note = 'Turns off the Edge sidebar, shopping assistant, widgets and first-run experience through Edge policies. Restart Edge. Other policies are preserved; OFF deletes only these values.' }
    [pscustomobject]@{ N = 73; Group = 'GPU'; Label = 'NVIDIA app + Control Panel'; Script = '73-NvidiaTools.ps1'; Risk = $false; Note = 'Diagnoses the adapter, NVIDIA driver, NVIDIA App, Control Panel, Store, winget, Windows Update and BITS, then names exactly what is missing. ON prints a numbered fix plan and, when the Store and its services are healthy, installs the Control Panel with winget from Microsoft Store (id 9NF8H0H7WMLT); otherwise it gives the exact wsreset/winget/driver commands and opens nvidia.com/drivers. A driver install always adds the Control Panel without the Store. OFF has nothing to undo.' }
    [pscustomobject]@{ N = 74; Group = 'GPU'; Label = 'NVIDIA telemetry service off'; Script = '74-NvidiaTelemetry.ps1'; Risk = $false; Note = 'Disables and stops NvTelemetryContainer when the NVIDIA App or driver installed it. Startup type is saved to ProgramData\AstraMax\NvidiaTelemetry.json; OFF restores it and starts the service if it was running. Splitting the driver install or the App install still works; the service is not deleted.' }
    [pscustomobject]@{ N = 75; Group = 'Privacy'; Label = 'Lock screen Spotlight off'; Script = '75-Spotlight.ps1'; Risk = $false; Note = 'Turns off the rotating Windows Spotlight lock screen and its tips overlay (RotatingLockScreenEnabled and RotatingLockScreenOverlayEnabled = 0). OFF removes both values, returning to the Windows default lock screen.' }
    [pscustomobject]@{ N = 76; Group = 'Shell'; Label = 'Post-update setup prompts off'; Script = '76-Scoobe.ps1'; Risk = $false; Note = 'Turns off the "finish setting up your device" nags after feature updates (ScoobeSystemSettingEnabled = 0). OFF removes the value, returning to the Windows default.' }
    [pscustomobject]@{ N = 77; Group = 'Shell'; Label = 'Recently added apps list off'; Script = '77-StartRecent.ps1'; Risk = $false; Note = 'Hides the recently added apps list in Start (Start_TrackProgs = 0). Start still shows pinned apps; OFF removes the value, returning to the Windows default. Sign out to finish.' }
    [pscustomobject]@{ N = 78; Group = 'Security'; Label = 'SmartScreen checks on'; Script = '78-SmartScreen.ps1'; Risk = $false; Note = 'Turns SmartScreen on (Warn) for apps and files and enables the policy. ON saves the previous values under ProgramData\AstraMax\Security; OFF restores them, or turns SmartScreen off (security trade-off) when no snapshot exists.' }
    [pscustomobject]@{ N = 79; Group = 'Network'; Label = 'LLMNR off'; Script = '79-Llmnr.ps1'; Risk = $false; Note = 'Disables LLMNR multicast name resolution through the DNSClient policy (EnableMulticast = 0). ON saves the previous policy value; OFF restores it or removes the value.' }
    [pscustomobject]@{ N = 80; Group = 'Security'; Label = 'AutoRun off (all drives)'; Script = '80-Autorun.ps1'; Risk = $false; Note = 'Sets NoDriveTypeAutoRun = 255 so AutoPlay/AutoRun is disabled for every drive type. ON saves the previous value; OFF restores it or removes the value.' }
    [pscustomobject]@{ N = 81; Group = 'Privacy'; Label = 'Security Center notifications off'; Script = '81-SecurityNotifications.ps1'; Risk = $false; Note = 'Turns off the Defender/Windows Security toast alerts for this user. The notifications page in Settings still works. OFF writes the Windows default back.' }
    [pscustomobject]@{ N = 82; Group = 'Privacy'; Label = 'Cloud clipboard sync off'; Script = '82-CloudClipboard.ps1'; Risk = $false; Note = 'Stops automatic clipboard upload to the Microsoft account (CloudClipboardAutomaticUpload = 0). Local clipboard history still works. OFF removes the value.' }
    [pscustomobject]@{ N = 83; Group = 'Shell'; Label = 'Game Bar startup tips off'; Script = '83-GameBarTips.ps1'; Risk = $false; Note = 'Stops the Game Bar startup panel and its tips (ShowStartupPanel = 0). The Game Bar itself and Win+G stay available. OFF writes 1.' }
    [pscustomobject]@{ N = 84; Group = 'Privacy'; Label = 'Online speech recognition off'; Script = '84-OnlineSpeech.ps1'; Risk = $false; Note = 'Declines cloud speech recognition for this user (OnlineSpeechPrivacy HasAccepted = 0). Dictation still works locally where Windows supports it; Windows may ask again after an update. OFF removes the value.' }
    [pscustomobject]@{ N = 85; Group = 'Privacy'; Label = 'Inking and typing personalization off'; Script = '85-InkTyping.ps1'; Risk = $false; Note = 'Stops Windows collecting typing and handwriting samples for its personal dictionary (both RestrictImplicit*Collection values = 1). OFF removes both values.' }
    [pscustomobject]@{ N = 86; Group = 'Privacy'; Label = 'Website language list access off'; Script = '86-LanguageList.ps1'; Risk = $false; Note = 'Websites can no longer read the Windows language list (HttpAcceptLanguageOptOut = 1). OFF removes the value.' }
    [pscustomobject]@{ N = 87; Group = 'Privacy'; Label = 'Tailored experiences off'; Script = '87-TailoredExperiences.ps1'; Risk = $false; Note = 'Stops Windows using diagnostic data for tailored tips and suggestions (TailoredExperiencesWithDiagnosticDataEnabled = 0). OFF removes the value.' }
    [pscustomobject]@{ N = 88; Group = 'Shell'; Label = 'Start recommendations off'; Script = '88-StartRecommendations.ps1'; Risk = $false; Note = 'Hides the Recommended section in Start (Start_IrisRecommendations = 0). Pinned apps stay. OFF removes the value so recommendations come back.' }
    [pscustomobject]@{ N = 89; Group = 'Shell'; Label = 'Hidden files shown'; Script = '89-HiddenFiles.ps1'; Risk = $false; Note = 'Shows hidden files and folders in Explorer (Hidden = 1). Protected operating-system files stay hidden. OFF writes 0.' }
    [pscustomobject]@{ N = 90; Group = 'Shell'; Label = 'Full path in the title bar'; Script = '90-FullPath.ps1'; Risk = $false; Note = 'Explorer windows show the complete folder path in the title bar (CabinetState FullPath = 1). OFF writes 0.' }
    [pscustomobject]@{ N = 91; Group = 'Shell'; Label = 'Small taskbar icons'; Script = '91-TaskbarSmallIcons.ps1'; Risk = $false; Note = 'Uses the small taskbar button size (TaskbarSmallIcons = 1). Sign out or restart Explorer to finish. OFF writes 0.' }
    [pscustomobject]@{ N = 92; Group = 'Shell'; Label = 'Taskbar preview hover delay off'; Script = '92-HoverDelay.ps1'; Risk = $false; Note = 'Shows taskbar thumbnails without the hover delay (ExtendedUIHoverTime = 0). Restart Explorer to finish. OFF removes the value.' }
    [pscustomobject]@{ N = 93; Group = 'Input'; Label = 'Fastest keyboard repeat'; Script = '93-KeyboardRepeat.ps1'; Risk = $false; Note = 'Shortest repeat delay and fastest repeat rate (KeyboardDelay 0, KeyboardSpeed 31). OFF restores the normal delay.' }
    [pscustomobject]@{ N = 94; Group = 'System'; Label = 'Communications ducking off'; Script = '94-AudioDucking.ps1'; Risk = $false; Note = 'Windows stops lowering other sounds during calls (UserDuckingPreference = 3). OFF removes the value.' }
    [pscustomobject]@{ N = 95; Group = 'System'; Label = 'Crash reporting dialogs off'; Script = '95-WerUi.ps1'; Risk = $false; Note = 'Hides Windows Error Reporting dialogs (DontShowUI = 1). Reports still follow the WER policy; this only hides the prompt. OFF removes the value.' }
    [pscustomobject]@{ N = 96; Group = 'Performance'; Label = 'Kernel paging executive'; Script = '96-PagingExecutive.ps1'; Risk = $false; Note = 'Keeps kernel-mode code resident instead of paging it out (DisablePagingExecutive = 1). Reboot to apply; wants 16 GB or more. ON saves the previous value; OFF restores it or removes it.' }
    [pscustomobject]@{ N = 97; Group = 'System'; Label = 'Automatic maintenance off'; Script = '97-Maintenance.ps1'; Risk = $false; Note = 'Stops the automatic maintenance window (MaintenanceDisabled = 1), so defrag, cleanup and health tasks only run when you start them. ON saves the previous value; OFF restores it or removes it.' }
    [pscustomobject]@{ N = 98; Group = 'System'; Label = 'Reopen apps after sign-in off'; Script = '98-RestartApps.ps1'; Risk = $false; Note = 'Stops Windows reopening apps that were running at shutdown (Winlogon RestartApps = 0). OFF removes the value.' }
    [pscustomobject]@{ N = 99; Group = 'Security'; Label = 'Clear pagefile at shutdown'; Script = '99-ClearPagefile.ps1'; Risk = $false; Note = 'Overwrites the pagefile on shutdown (ClearPageFileAtShutdown = 1). Shutdown takes longer, especially on hard drives. ON saves the previous value; OFF restores it or removes it.' }
    [pscustomobject]@{ N = 100; Group = 'Security'; Label = 'Windows Script Host off'; Script = '100-Wsh.ps1'; Risk = $true; Note = 'Disables Windows Script Host (Enabled = 0), which stops .vbs and .js scripts from running. Some installers and game mod tools rely on them. ON saves the previous value; OFF restores it or removes it.' }
)

$AstraGroups = 'All', 'Performance', 'CPU', 'GPU', 'Gaming', 'Network', 'Privacy', 'Shell', 'System', 'Input', 'Appearance', 'Security', 'Debloat'
